#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <mruby.h>
#include <mruby/compile.h>

int LLVMFuzzerTestOneInput(const uint8_t *Data, size_t size) {
    if (size < 1) return 0;
    char *code = malloc(size+1);
    memcpy(code, Data, size);
    code[size] = '\0';
    mrb_state *mrb = mrb_open();
    if (!mrb) { free(code); return 0; }
    mrb_load_string(mrb, code);
    mrb_close(mrb);
    free(code);
    return 0;
}

int main(int argc, char **argv) {
    if (argc < 2) { fprintf(stderr, "usage: %s file\n", argv[0]); return 2; }
    FILE *f = fopen(argv[1], "rb");
    if (!f) { perror("fopen"); return 2; }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    uint8_t *buf = malloc(sz);
    fread(buf, 1, sz, f);
    fclose(f);
    int r = LLVMFuzzerTestOneInput(buf, (size_t)sz);
    free(buf);
    return r;
}
EOF
SRC=/workspace/repo-vul/src-vul
CFLAGS="-std=gnu99 -g -O0 -fsanitize=address,undefined -DMRB_DEBUG -DMRB_USE_COMPLEX -DMRB_USE_RATIONAL -I$SRC/include -I$SRC/build/host/include -I$SRC/mrbgems/mruby-time/include -I$SRC/mrbgems/mruby-io/include"
gcc $CFLAGS -c /tmp/mrbbuild/driver.c -o /tmp/mrbbuild/driver.o 2>&1 | head
echo "=== link ==="
g++ -fsanitize=address,undefined -g -O0 /tmp/mrbbuild/driver.o -L/tmp/mrbbuild -lmruby -lm -o /tmp/mrbbuild/fuzz_test 2>&1 | head -30
echo "exit: $?"
ls -la /tmp/mrbbuild/fuzz_test 2>/dev/null

